import pandas as pd,numpy as np,glob
from scipy.optimize import least_squares
files=sorted(glob.glob('train/*.csv'))
D={f:pd.read_csv(f) for f in files}
def sim(p,d,dec=5):
    Kq,Kqv,Tq,Kpv,Kpf,Tw,Tp=p
    t=d.time_s.values[::dec]; V=d.voltage_pu.values[::dec]; th=d.bus_angle_rad.values[::dec]; Vs=d.voltage_setpoint_pu.values[::dec]
    P0,Q0=d.active_power_pu.values[0],d.reactive_power_pu.values[0]; V0=V[0]
    n=len(t); Pm=np.empty(n); Qm=np.empty(n)
    q=Q0; pc=P0; thf=th[0]; dt=t[1]-t[0]
    for i in range(n):
        Pm[i]=pc-Kpf*(th[i]-thf); Qm[i]=q
        qref=Q0+Kq*(Vs[i]-V0)-Kqv*(V[i]-V0)
        pref=P0-Kpv*(V[i]-V0)
        q+=dt*(qref-q)/Tq; pc+=dt*(pref-pc)/Tp; thf+=dt*(th[i]-thf)/Tw
    return t,Pm,Qm,d.active_power_pu.values[::dec],d.reactive_power_pu.values[::dec]
def res(p,names):
    out=[]
    for f in names:
        t,Pm,Qm,P,Q=sim(p,D[f]); out+= [Pm-P,Qm-Q]
    return np.concatenate(out)
best=None
for Tq0 in [0.02,0.1,0.5]:
  for Tp0 in [0.02,0.2]:
    p0=[2.5,1.0,Tq0,0.5,5.0,2.0,Tp0]
    r=least_squares(res,p0,args=(files,),bounds=([0,-20,0.001,-20,-200,0.05,0.001],[20,20,5,20,200,50,5]))
    c=np.sqrt(np.mean(r.fun**2)); print(np.round(r.x,4),c)
    if best is None or c<best[1]: best=(r.x,c)
np.save('p1.npy',best[0])
for f in files: print(f, np.sqrt(np.mean(res(best[0],[f])**2)))

